const item = $input.first();
const body = item.json.body || {};
const slug = (body.client_slug || '').toLowerCase().replace(/[^a-z0-9-]/g, '-');
const domain = `${slug}.arcuscloud.com.br`;
// O n8n nomeia o campo binario com um sufixo (ex: 'logo0'), nao exatamente
// 'logo' -- pega a primeira propriedade binaria disponivel. E o conteudo
// real (quando o n8n guarda binarios em disco, nao em memoria) precisa
// ser lido via helper, .data sozinho e so uma referencia interna
// (ex: 'filesystem-v2:...'), nao a string base64 de verdade.
let logoDataUri = '';
let logoMime = '';
if (item.binary) {
  const keys = Object.keys(item.binary);
  if (keys.length) {
    const propName = keys[0];
    const meta = item.binary[propName];
    const buffer = await this.helpers.getBinaryDataBuffer(0, propName);
    logoDataUri = `data:${meta.mimeType};base64,${buffer.toString('base64')}`;
    logoMime = meta.mimeType;
  }
}
return [{
  json: {
    client_slug: slug,
    client_domain: domain,
    client_name: body.client_name || slug,
    client_email_to: body.client_email_to || '',
    client_contact_name: body.client_contact_name || '',
    client_primary_color: body.client_primary_color || '#0EA5E9',
    logo_data_uri: logoDataUri,
    logo_mime: logoMime,
  }
}];

const cfg = $('Preparar Dados').first().json;
const tpl = $input.first().json;
const nodesCopy = JSON.parse(JSON.stringify(tpl.nodes));
for (const n of nodesCopy) {
  if (n.name === 'Configuração') {
    for (const a of n.parameters.assignments.assignments) {
      if (a.name === 'client_slug') a.value = cfg.client_slug;
      else if (a.name === 'client_name') a.value = cfg.client_name;
      else if (a.name === 'client_email_to') a.value = cfg.client_email_to;
      else if (a.name === 'client_logo_url') a.value = cfg.logo_data_uri;
      else if (a.name === 'client_primary_color') a.value = cfg.client_primary_color;
    }
  }
  if (n.name === 'Webhook Gerar Agora') {
    n.parameters.path = 'report-generate-' + cfg.client_slug;
    n.webhookId = 'report-generate-' + cfg.client_slug;
  }
}
const payload = {
  name: 'Relatório Mensal — ' + cfg.client_name,
  nodes: nodesCopy,
  connections: tpl.connections,
  settings: tpl.settings,
};
return [{ json: payload }];

const cfg = $('Preparar Dados').first().json;
const newWfId = $('Criar Workflow do Cliente').first().json.id;
const ext = (cfg.logo_mime || '').includes('svg') ? 'svg' : 'png';
const logoB64 = (cfg.logo_data_uri || '').split(',')[1] || '';
const genUrl = `https://n8n.arcuscloud.com.br/webhook/report-generate-${cfg.client_slug}`;
const histUrl = `https://n8n.arcuscloud.com.br/webhook/report-history?workflow_id=${newWfId}`;
const safeName = cfg.client_name.replace(/"/g, '');
const commands = [
  'set -e',
  'export HOME=/root',
  'cd /opt/setup-platform 2>/dev/null || cd /root/setup-platform',
  'git pull --ff-only',
  "echo '" + logoB64 + "' | base64 -d > /tmp/prov-logo." + ext,
  'export REPORT_GENERATE_URL=' + genUrl,
  'export REPORT_HISTORY_URL=' + histUrl,
  'LOGO_URI="data:' + cfg.logo_mime + ';base64,$(base64 -w0 /tmp/prov-logo.' + ext + ')"',
  'bash modules/client-dashboard/new-client.sh ' + cfg.client_slug + ' ' + cfg.client_domain + ' "' + cfg.client_primary_color + '" "$LOGO_URI" "' + safeName + '"',
];
return [{ json: { commands, client_domain: cfg.client_domain, client_name: cfg.client_name, new_workflow_id: newWfId } }];
